// The extension's icons in public/icons:
// - icon-{16,32,48,128}.png and icon-on-dark-*: copied from the brand kit
//   (brand/png, generated by brand/scripts/build.mjs), for the extensions page
//   and the stores: Onyx, and its Paper twin for dark surfaces.
// - toolbar-{16,24,32}.png and toolbar-on-dark-*: drawn here for the toolbar
//   button. The brand's pixel arrow keeps a gap between its cells, which at
//   toolbar size (and once the browser scales it for 125% or 150% displays)
//   breaks into a grid of dots. These draw the arrow as one solid stepped
//   silhouette on whole pixels, per size, so it stays an arrow.
// `--check` fails when any file is stale instead of writing it.
import { mkdirSync, readFileSync, writeFileSync, existsSync } from "node:fs";
import sharp from "sharp";

const SIZES = [16, 32, 48, 128];
const VARIANTS = ["icon", "icon-on-dark"];
const brand = new URL("../../../brand/png/", import.meta.url);
const out = new URL("../public/icons/", import.meta.url);
const check = process.argv.includes("--check");

/** The arrow as [x, y, width, height] rectangles, per toolbar size. */
const ARROW_16 = [
  [6, 3, 4, 5],
  [3, 8, 10, 1],
  [4, 9, 8, 1],
  [5, 10, 6, 1],
  [6, 11, 4, 1],
  [7, 12, 2, 1],
];
const ARROWS = {
  16: ARROW_16,
  24: [[9, 4, 6, 8], ...[16, 14, 12, 10, 8, 6, 4, 2].map((w, i) => [12 - w / 2, 12 + i, w, 1])],
  32: ARROW_16.map((r) => r.map((v) => v * 2)),
};

/** One toolbar icon: the tile, a hairline edge so it holds on any toolbar, the arrow. */
function toolbarSvg(size, onDark) {
  const r = Math.round(size * 0.22);
  const [top, bottom, arrow, edge] = onDark
    ? ["#FFFFFF", "#ECEDEF", "#0A0A0B", "rgba(0,0,0,0.10)"]
    : ["#2E3033", "#0A0A0B", "#FFFFFF", "rgba(255,255,255,0.16)"];
  const rects = ARROWS[size]
    .map(([x, y, w, h]) => `<rect x="${x}" y="${y}" width="${w}" height="${h}"/>`)
    .join("");
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 ${size} ${size}">
<defs><linearGradient id="g" x1="0" y1="0" x2="0.4" y2="1"><stop offset="0" stop-color="${top}"/><stop offset="1" stop-color="${bottom}"/></linearGradient></defs>
<rect width="${size}" height="${size}" rx="${r}" fill="url(#g)"/>
<rect x="0.5" y="0.5" width="${size - 1}" height="${size - 1}" rx="${r - 0.5}" fill="none" stroke="${edge}"/>
<g fill="${arrow}" shape-rendering="crispEdges">${rects}</g>
</svg>`;
}

async function toolbarPng(size, onDark) {
  return sharp(Buffer.from(toolbarSvg(size, onDark)))
    .png({ compressionLevel: 9 })
    .toBuffer();
}

mkdirSync(out, { recursive: true });
const stale = [];
async function put(name, data) {
  const target = new URL(name, out);
  if (existsSync(target) && readFileSync(target).equals(data)) return;
  if (check) stale.push(name);
  else writeFileSync(target, data);
}

for (const variant of VARIANTS) {
  for (const size of SIZES) {
    const name = `${variant}-${size}.png`;
    await put(name, readFileSync(new URL(name, brand)));
  }
}
for (const size of Object.keys(ARROWS).map(Number)) {
  await put(`toolbar-${size}.png`, await toolbarPng(size, false));
  await put(`toolbar-on-dark-${size}.png`, await toolbarPng(size, true));
}

if (stale.length > 0) {
  console.error(
    `public/icons is stale (${stale.join(", ")}): run pnpm --filter @boltget/extension icons`,
  );
  process.exit(1);
}
